203	bool myvendor_sys_phone_gnss_get(myvendor_sys_gnss_t *out)
204	{
205	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
206	  struct companion_gnss_fix fix;
207	
208	  if (!companion_bridge_gnss_get(&fix))
209	    {
210	      if (out != NULL)
211	        {
212	          memset(out, 0, sizeof(*out));
213	        }
214	
215	      return false;
216	    }
217	
218	  if (out != NULL)
219	    {
220	      /* 先整份清零再逐字段填。手机协议（0xFF14）里没有 PVT 那几项
221	       * （gSpeed / sAcc / fixType），它们必须明确为 0/false —— 调用方
222	       * （bicycle_runtime 的路由）用的是**未清零的栈上结构**，漏掉就会把栈垃圾
223	       * 当成 pvt_valid / sAcc 去用（PVT 走得通之后才有的坑）。 */
224	      memset(out, 0, sizeof(*out));
225	      out->valid = fix.fix_quality != COMPANION_FIX_NONE;
226	      out->alive = true;
227	      out->lat_e7 = fix.lat_e7;
228	      out->lon_e7 = fix.lon_e7;
229	      out->alt_mm = fix.alt_mm;
230	      out->speed_centi_kmh = fix.speed_centi_kmh;
231	      out->course_deg = fix.course_deg;
232	      out->satellites = fix.satellites;
233	      out->sats_heard = fix.satellites;
234	      out->sats_in_view = fix.satellites;
235	      out->fix_quality = fix.fix_quality;
236	      out->hdop_x10 = fix.hdop_x10;
237	      out->utc_sec = fix.utc_sec;
238	      /* 手机协议（0xFF14，24 B）只带一个总星数，没有 GSV 细分，所以上面三个
239	       * 星数字段同值；时间戳取 bridge 记录的接收时刻，让消费方能算年龄。 */
240	      out->stamp_ms = companion_bridge_gnss_stamp_ms();
241	    }
242	
243	  return true;
244	#else
245	  if (out != NULL)
246	    {
247	      memset(out, 0, sizeof(*out));
248	    }
249	
250	  return false;
251	#endif
252	}
