259	bool myvendor_sys_gnss_eph_busy(void)
260	{
261	  myvendor_sys_gnss_t g;
262	
263	  /* 「星历同步」不能比读线程活得久。
264	   *
265	   * `g_eph_busy` 在注入开始时置位、注入**结束**才清。读线程在注入中途卡死时
266	   * （现场第 4 次：`phase=read-poll`、`busy=1`，diag 每 30 s 重试回收都失败）
267	   * 没人清它 —— 而 UI 判「星历同步」的那一支**排在最前面**，会直接盖掉后面
268	   * 「无数据 / GNSS 失效」的分支。结果屏幕一直显示"星历同步"，而 GNSS 其实
269	   * 已经死了、那个状态永远不会变。这与 BLE 侧那个"粘滞 connected"是同一类毛病：
270	   * 状态标志没有时限、不从事实重新推导。
271	   *
272	   * 这里按**读线程健康**裁掉：只有 HL_OK 才承认"正在同步星历"。判据就在 UI 拿到
273	   * 的那份快照里（`rd_state`，见 myvendor_sys_gnss_health_e），所以这一层不需要
274	   * 额外时基，也不需要读线程配合。 */
275	  if (!myvendor_sys_onboard_gnss_get(&g) ||
276	      g.rd_state != MYVENDOR_SYS_GNSS_HL_OK)
277	    {
278	      return false;
279	    }
280	
281	  return myvendor_gnss_eph_busy();
282	}
