509	/**
510	 * @brief 有符号定点数，不用 %f（NSH 小栈上 dtoa 会打穿）。
511	 *
512	 * @param v      值。
513	 * @param scale  10=一位小数，100=两位。
514	 */
515	static void sys_print_fixed(float v, unsigned scale)
516	{
517	  int neg;
518	  int scaled;
519	  unsigned mag;
520	  unsigned frac;
521	
522	  if (scale != 10u && scale != 100u)
523	    {
524	      scale = 100u;
525	    }
526	
527	  neg = (v < 0.0f);
528	  if (neg)
529	    {
530	      v = -v;
531	    }
532	
533	  scaled = (int)(v * (float)scale + 0.5f);
534	  if (scaled < 0)
535	    {
536	      scaled = 0;
537	    }
538	
539	  mag = (unsigned)scaled;
540	  frac = mag % scale;
541	  mag /= scale;
542	  if (neg && (mag != 0 || frac != 0))
543	    {
544	      putchar('-');
545	    }
546	
547	  if (scale == 100u)
548	    {
549	      printf("%u.%02u", mag, frac);
550	    }
551	  else
552	    {
553	      printf("%u.%u", mag, frac);
554	    }
555	}
