557	/**
558	 * @brief 打印一份 GNSS 快照（板载或手机）的年龄。
559	 *
560	 * @details
561	 * stamp_ms 是本份数据的采样时刻。0 表示来源没给时间戳（未知），此时打 "--"
562	 * 而不是打一个看起来很小的假年龄。消费方必须能区分"刚采到"和"恢复期里
563	 * 被 hold 住的旧值"，否则 sat/age 一起看会得出错误结论。
564	 *
565	 * @param g 快照。
566	 */
567	static void sys_print_gnss_age(const myvendor_sys_gnss_t *g)
568	{
569	  if (g->stamp_ms == 0)
570	    {
571	      printf("  age --");
572	      return;
573	    }
574	
575	  printf("  age %u.%03u s",
576	         (unsigned)(myvendor_mono_elapsed_ms(myvendor_mono_ms(),
577	                                            g->stamp_ms) / 1000u),
578	         (unsigned)(myvendor_mono_elapsed_ms(myvendor_mono_ms(),
579	                                            g->stamp_ms) % 1000u));
580	}
