582	void myvendor_sys_gnss_print_pvt(const myvendor_sys_gnss_t *g)
583	{
584	  const char *fix;
585	
586	  if (g == NULL || !g->pvt_valid)
587	    {
588	      return;
589	    }
590	
591	  /* fixType 打成 2D/3D 字样，**不要打数字**：同一行里 `q %u` 是 GGA/GSA 的
592	   * 定位质量（0 无 / 1 2D / 2 3D），PVT 的 fixType 是另一套编号
593	   * （0 无 / 2 2D / 3 3D）—— 两个 "2" 含义相反，数字并排会被读成一致。
594	   * 现场第一次看就撞上了：`q 2`（3D）配 `fix 2`（2D），实际是两边不一致。 */
595	  switch (g->pvt_fix_type)
596	    {
597	      case 2:  fix = "2D"; break;
598	      case 3:  fix = "3D"; break;
599	      case 4:  fix = "DR"; break;
600	      case 5:  fix = "time"; break;
601	      default: fix = "none"; break;
602	    }
603	
604	  /* 单位：gs 与 speed_centi_kmh 同为 0.01 km/h；sacc 是 mm/s，这里打成 m/s
605	   * （两位小数），与 `gnss: pvt` 那行的 mm/s 是同一条数据。 */
606	  printf("  gs %u.%02u km/h  sacc %u.%02u m/s  pvt %s ok %u",
607	         (unsigned)(g->speed_pvt_centi_kmh / 100u),
