673	/** @brief 时钟源频率；未使能的 DLL 由 HAL 返回 0。 */
674	static uint32_t sys_clk_src_hz(uint8_t src)
675	{
676	  if (src == RCC_CLK_SRC_DLL2)
677	    {
678	      return HAL_RCC_HCPU_GetDLL2Freq();
679	    }
680	
681	  if (src == RCC_CLK_SRC_DLL1)
682	    {
683	      return HAL_RCC_HCPU_GetDLL1Freq();
684	    }
685	
686	  return HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
687	}
