689	/**
690	 * @brief 推一个 MPI/FLASH 模块的实际时钟。
691	 *
692	 * @details
693	 * hz = 时钟源 / MPI PSCLR.DIV。PSCLR 是 MPI 的直接整数分频
694	 * （HAL_FLASH_SET_CLK_rom 就是 `PSCLR = div`），而软件分频变量
695	 * BSP_GetFlashxDIV() 只在 HAL_MPI_PSRAM_Init 时被写进硬件、之后可能过期，
696	 * 所以这里以硬件为准，软件值只带出来对照。
697	 *
698	 * @param clk_module RCC_CLK_MOD_FLASH1 / FLASH2。
699	 * @param mpi 该模块的 MPI 实例（hwp_qspi1 / hwp_qspi2）。
700	 * @param sw_div BSP_GetFlashxDIV()，仅用于对照。
701	 * @param hz 输出频率。
702	 * @param src 输出时钟源。
703	 * @param psclr 输出硬件分频。
704	 * @param sw 输出软件分频。
705	 */
706	static void sys_clk_probe_flash(int clk_module, MPI_TypeDef *mpi,
707	                                uint16_t sw_div, uint32_t *hz, uint8_t *src,
708	                                uint8_t *psclr, uint8_t *sw)
709	{
710	  uint32_t base;
711	
712	  *src = (uint8_t)HAL_RCC_HCPU_GetClockSrc(clk_module);
713	  *psclr = (mpi != NULL)
714	               ? (uint8_t)GET_REG_VAL(mpi->PSCLR, MPI_PSCLR_DIV_Msk,
715	                                      MPI_PSCLR_DIV_Pos)
716	               : 0u;
717	  *sw = (uint8_t)(sw_div > 255u ? 255u : sw_div);
718	
719	  base = sys_clk_src_hz(*src);
720	  *hz = base / ((*psclr != 0u) ? *psclr : 1u);
721	}
722	
723	void myvendor_sys_clk_get(myvendor_sys_clk_t *out)
724	{
725	  if (out == NULL)
726	    {
727	      return;
728	    }
729	
730	  memset(out, 0, sizeof(*out));
731	
732	  out->sysclk_hz = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
733	  out->hclk_hz = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
734	
735	  /* DLL 只如实上报使能位与频率，不碰任何配置。 */
736	  if ((hwp_hpsys_rcc->DLL1CR & HPSYS_RCC_DLL1CR_EN) != 0u)
737	    {
738	      out->dll1_en = 1u;
739	      out->dll1_hz = HAL_RCC_HCPU_GetDLL1Freq();
740	    }
741	
742	  if ((hwp_hpsys_rcc->DLL2CR & HPSYS_RCC_DLL2CR_EN) != 0u)
743	    {
744	      out->dll2_en = 1u;
745	      out->dll2_hz = HAL_RCC_HCPU_GetDLL2Freq();
746	    }
747	
748	  sys_clk_probe_flash(RCC_CLK_MOD_FLASH1, hwp_qspi1, BSP_GetFlash1DIV(),
749	                      &out->flash1_hz, &out->flash1_src, &out->flash1_psclr,
750	                      &out->flash1_sw_div);
751	  sys_clk_probe_flash(RCC_CLK_MOD_FLASH2, hwp_qspi2, BSP_GetFlash2DIV(),
752	                      &out->flash2_hz, &out->flash2_src, &out->flash2_psclr,
753	                      &out->flash2_sw_div);
754	
755	  out->mismatch = (out->flash1_psclr != out->flash1_sw_div ||
756	                   out->flash2_psclr != out->flash2_sw_div);
757	}
