759	/** @brief 汇总行：一行看清 SYSCLK/HCLK/PSRAM/NAND 的实际频率。 */
760	static void sys_print_clk(void)
761	{
762	  myvendor_sys_clk_t c;
763	
764	  myvendor_sys_clk_get(&c);
765	  printf("  clk     sys %u MHz  hclk %u MHz  psram %u MHz (%s/%u)  nand %u MHz (%s/%u)\n",
766	         (unsigned)(c.sysclk_hz / 1000000u), (unsigned)(c.hclk_hz / 1000000u),
767	         (unsigned)(c.flash1_hz / 1000000u),
768	         myvendor_sys_clk_src_name(c.flash1_src), (unsigned)c.flash1_psclr,
769	         (unsigned)(c.flash2_hz / 1000000u),
770	         myvendor_sys_clk_src_name(c.flash2_src), (unsigned)c.flash2_psclr);
771	
772	  if (c.mismatch)
773	    {
774	      /* 软件分频变量与硬件 PSCLR 不一致时明确点出来：按 sw_div 算出来的频率
775	       * 是错的，以上一行的 psclr 为准。 */
776	      printf("  clk     MISMATCH sw_div psram=%u nand=%u  vs hw psclr psram=%u nand=%u\n",
777	             (unsigned)c.flash1_sw_div, (unsigned)c.flash2_sw_div,
778	             (unsigned)c.flash1_psclr, (unsigned)c.flash2_psclr);
779	    }
780	}
