42	/**
43	 * @brief 有符号定点数，不用 %f（sys 任务栈上 dtoa 会打穿 NSH）。
44	 *
45	 * @param v      值。
46	 * @param scale  10=一位小数，100=两位。
47	 */
48	static void sys_print_fixed(float v, unsigned scale)
49	{
50	  int neg;
51	  int scaled;
52	  unsigned mag;
53	  unsigned frac;
54	
55	  if (scale != 10u && scale != 100u)
56	    {
57	      scale = 100u;
58	    }
59	
60	  neg = (v < 0.0f);
61	  if (neg)
62	    {
63	      v = -v;
64	    }
65	
66	  scaled = (int)(v * (float)scale + 0.5f);
67	  if (scaled < 0)
68	    {
69	      scaled = 0;
70	    }
71	
72	  mag = (unsigned)scaled;
73	  frac = mag % scale;
74	  mag /= scale;
75	  if (neg && (mag != 0 || frac != 0))
76	    {
77	      putchar('-');
78	    }
79	
80	  if (scale == 100u)
81	    {
82	      printf("%u.%02u", mag, frac);
83	    }
84	  else
85	    {
86	      printf("%u.%u", mag, frac);
87	    }
88	}
