228	          if (ui.slot[k].addr[0] != 0 || ui.slot[k].addr[1] != 0 ||
229	              ui.slot[k].addr[2] != 0 || ui.slot[k].addr[3] != 0 ||
230	              ui.slot[k].addr[4] != 0 || ui.slot[k].addr[5] != 0)
231	            {
