244	      for (i = 0; i < ui.found_n; i++)
245	        {
246	          printf("sys found %u  rssi %d  kinds 0x%x%s  %02x:%02x:%02x:%02x:%02x:%02x  %s\n",
247	                 (unsigned)ui.found[i].table_idx, (int)ui.found[i].rssi,
