134	/**
135	 * @brief 读 persist 文件中的十进制整数。
136	 * @return 成功为解析值，否则 @p fallback。
137	 */
138	static int persist_get_i32(const char *key, int32_t fallback)
139	{
140	  char buf[32];
141	  int fd;
142	  ssize_t n;
143	  char *end;
144	  long v;
145	
146	  if (key == NULL || key[0] == '\0')
147	    {
148	      return fallback;
149	    }
150	
151	  fd = persist_open_ro(key);
152	  if (fd < 0)
153	    {
154	      return fallback;
155	    }
156	
157	  n = read(fd, buf, sizeof(buf) - 1);
158	  close(fd);
159	  if (n <= 0)
160	    {
161	      return fallback;
162	    }
163	
164	  buf[n] = '\0';
165	  v = strtol(buf, &end, 10);
166	  if (end == buf)
167	    {
168	      return fallback;
169	    }
170	
171	  return (int32_t)v;
172	}
