224	static bool last_pos_ok(int32_t lon_e7, int32_t lat_e7)
225	{
226	  int32_t a_lon;
227	  int32_t a_lat;
228	
229	  if (lon_e7 == 0 && lat_e7 == 0)
230	    {
231	      return false;
232	    }
233	
234	  a_lon = lon_e7 < 0 ? -lon_e7 : lon_e7;
235	  a_lat = lat_e7 < 0 ? -lat_e7 : lat_e7;
236	  if (a_lon < 10000 && a_lat < 10000)
237	    {
238	      return false;
239	    }
240	
241	  /* 全国图：72E–136E、17N–54N。超出当异常，开机用地图默认点。 */
242	  if (lon_e7 < 720000000 || lon_e7 > 1360000000)
243	    {
244	      return false;
245	    }
246	
247	  if (lat_e7 < 170000000 || lat_e7 > 540000000)
248	    {
249	      return false;
250	    }
251	
252	  return true;
253	}
