255	/**
256	 * @brief 把整数写入 persist 文件（覆盖）。
257	 * @return 0 成功；负值为失败原因（mkdir / open / write 的 errno）。
258	 */
259	static int persist_set_i32(const char *key, int32_t v)
260	{
261	  char path[80];
262	  char buf[32];
263	  int fd;
264	  int n;
265	
266	  if (key == NULL || key[0] == '\0')
267	    {
268	      return -EINVAL;
269	    }
270	
271	  if (persist_ensure_db() < 0)
272	    {
273	      int err = errno;
274	
275	      syslog(LOG_WARNING, "ctl: persist mkdir %s errno=%d", DEVCTL_KV_DB_PATH,
276	             err);
277	      return -err;
278	    }
279	
280	  persist_make_path(path, sizeof(path), key);
281	  n = snprintf(buf, sizeof(buf), "%ld\n", (long)v);
282	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
283	  if (fd < 0)
284	    {
285	      int err = errno;
286	
287	      syslog(LOG_WARNING, "ctl: persist %s failed errno=%d", key, err);
288	      return -err;
289	    }
290	
291	  if (write(fd, buf, (size_t)n) != n)
292	    {
293	      int err = errno;
294	
295	      syslog(LOG_WARNING, "ctl: persist %s write errno=%d", key, err);
296	      close(fd);
297	      return -err;
298	    }
299	
300	  close(fd);
301	  return 0;
302	}
