305	{
306	  static const uint8_t z[MYVENDOR_DEVCTL_SENSOR_ADDR_LEN];
307	
308	  return addr == NULL ||
309	         memcmp(addr, z, MYVENDOR_DEVCTL_SENSOR_ADDR_LEN) == 0;
