318	static void srec_mac_fmt(const uint8_t *addr, char *buf, size_t n)
319	{
320	  snprintf(buf, n, "%02X:%02X:%02X:%02X:%02X:%02X",
321	           addr[5], addr[4], addr[3], addr[2], addr[1], addr[0]);
322	}
323	
324	static bool srec_mac_parse(const char *text, uint8_t *addr)
325	{
326	  unsigned v[6];
327	  int i;
328	
329	  if (text == NULL || addr == NULL)
330	    {
331	      return false;
332	    }
333	
334	  if (sscanf(text, "%2x:%2x:%2x:%2x:%2x:%2x",
335	             &v[5], &v[4], &v[3], &v[2], &v[1], &v[0]) != 6)
336	    {
337	      return false;
338	    }
339	
340	  for (i = 0; i < 6; i++)
341	    {
342	      if (v[i] > 255u)
343	        {
344	          return false;
345	        }
346	
347	      addr[i] = (uint8_t)v[i];
348	    }
349	
350	  return !srec_addr_empty(addr);
351	}
