353	static void srec_name_copy(char *dst, size_t n, const char *src)
354	{
355	  size_t i;
356	
357	  if (dst == NULL || n == 0)
358	    {
359	      return;
360	    }
361	
362	  memset(dst, 0, n);
363	  if (src == NULL)
364	    {
365	      return;
366	    }
367	
368	  for (i = 0; i + 1u < n && src[i] != '\0'; i++)
369	    {
370	      char c = src[i];
371	
372	      if (c == '\t' || c == '\n' || c == '\r')
373	        {
374	          c = ' ';
375	        }
376	
377	      dst[i] = c;
378	    }
379	}
