382	{
383	  FILE *fp;
384	  uint8_t i;
385	  char mac[18];
386	
387	  fp = fopen(DEVCTL_SENSORS_TMP, "w");
388	  if (fp == NULL)
389	    {
390	      return -errno;
391	    }
392	
393	  for (i = 0; i < g_srec_n; i++)
394	    {
395	      srec_mac_fmt(g_srec[i].addr, mac, sizeof(mac));
396	      if (fprintf(fp, "%u\t%u\t%s\t%s\t%u\n",
397	                  (unsigned)g_srec[i].kind,
398	                  (unsigned)g_srec[i].addr_type,
399	                  mac,
400	                  g_srec[i].name[0] != '\0' ? g_srec[i].name : "-",
401	                  g_srec[i].autorc ? 1u : 0u) < 0)
402	        {
403	          fclose(fp);
404	          unlink(DEVCTL_SENSORS_TMP);
405	          return -EIO;
406	        }
407	    }
408	
409	  if (fclose(fp) != 0)
410	    {
411	      unlink(DEVCTL_SENSORS_TMP);
412	      return -EIO;
413	    }
414	
415	  if (rename(DEVCTL_SENSORS_TMP, MYVENDOR_DEVCTL_SENSORS_PATH) != 0)
416	    {
417	      unlink(DEVCTL_SENSORS_TMP);
418	      return -errno;
419	    }
420	
421	  g_srec_gen++;
422	  return 0;
423	}
