425	static void srec_load_locked(void)
426	{
427	  FILE *fp;
428	  char line[160];
429	  bool seen_kind[3] = { false, false, false };
430	
431	  g_srec_n = 0;
432	  memset(g_srec, 0, sizeof(g_srec));
433	  g_srec_ready = true;
434	
435	  fp = fopen(MYVENDOR_DEVCTL_SENSORS_PATH, "r");
436	  if (fp == NULL)
437	    {
438	      /* 文件不存在（首启）是正常的；其它错误必须说出来 —— 否则「连过但开机
439	       * 不回连」分不清是**没保存**还是**没加载**（FS 没挂 / IO 错）。 */
440	      if (errno != ENOENT)
441	        {
442	          syslog(LOG_ERR, "devctl: sensors load %s failed: %d\n",
443	                 MYVENDOR_DEVCTL_SENSORS_PATH, errno);
444	        }
445	
446	      return;
447	    }
448	
449	  while (fgets(line, sizeof(line), fp) != NULL &&
450	         g_srec_n < MYVENDOR_DEVCTL_SENSOR_REC_MAX)
451	    {
452	      char *kind_text;
453	      char *type_text;
454	      char *mac_text;
455	      char *name_text;
456	      char *auto_text;
457	      char *save = NULL;
458	      size_t len = strlen(line);
459	      unsigned kind;
460	      unsigned addr_type;
461	      unsigned autorc;
462	      myvendor_devctl_sensor_rec_t rec;
463	
464	      if (len > 0 && line[len - 1] == '\n')
465	        {
466	          line[--len] = '\0';
467	        }
468	
469	      if (len > 0 && line[len - 1] == '\r')
470	        {
471	          line[--len] = '\0';
472	        }
473	
474	      if (len == 0)
475	        {
476	          continue;
477	        }
478	
479	      kind_text = strtok_r(line, "\t", &save);
480	      type_text = strtok_r(NULL, "\t", &save);
481	      mac_text = strtok_r(NULL, "\t", &save);
482	      name_text = strtok_r(NULL, "\t", &save);
483	      auto_text = strtok_r(NULL, "\t", &save);
484	      if (kind_text == NULL || type_text == NULL || mac_text == NULL ||
485	          name_text == NULL || auto_text == NULL)
486	        {
487	          continue;
488	        }
489	
490	      kind = (unsigned)strtoul(kind_text, NULL, 10);
491	      addr_type = (unsigned)strtoul(type_text, NULL, 10);
492	      autorc = (unsigned)strtoul(auto_text, NULL, 10);
493	      if (kind > MYVENDOR_DEVCTL_SENSOR_KIND_CPS)
494	        {
495	          continue;
496	        }
497	
498	      memset(&rec, 0, sizeof(rec));
499	      if (!srec_mac_parse(mac_text, rec.addr))
500	        {
501	          continue;
502	        }
503	
504	      rec.kind = (uint8_t)kind;
505	      rec.addr_type = (uint8_t)addr_type;
506	      if (strcmp(name_text, "-") != 0)
507	        {
508	          srec_name_copy(rec.name, sizeof(rec.name), name_text);
509	        }
510	
511	      rec.autorc = (autorc != 0) && !seen_kind[kind];
512	      if (rec.autorc)
513	        {
514	          seen_kind[kind] = true;
515	        }
516	
517	      g_srec[g_srec_n++] = rec;
518	    }
519	
520	  fclose(fp);
521	}
522	
523	static void srec_ensure_locked(void)
524	{
525	  if (!g_srec_ready)
526	    {
527	      srec_load_locked();
528	    }
529	}
