578	      printf("sys rec %u  %s  type %u  %s  autorc %u  %s\n", (unsigned)i,
579	             srec_kind_name(recs[i].kind), (unsigned)recs[i].addr_type, mac,
580	             recs[i].autorc ? 1u : 0u,
581	             recs[i].name[0] != '\0' ? recs[i].name : "-");
582	    }
583	}
