585	/**
586	 * @brief 回连对账：记录（持久）↔ 槽位目标（本次开机）。
587	 *
588	 * @details
589	 * 回连**只**该由 `autorc` 记录驱动：武装在 `companion_sensor_autorc_all()`
590	 * → `ble_sensor_connect_addr()`，扫描回调本身不再替槽位挑设备（见
591	 * `docs/ble/ble_sensor.md` §3.9.1）。于是两个方向相反的问题在同一条判据上：
592	 *
593	 *   - **记录有 ★、槽位地址空** → 武装没上（BLE 没 started、或记录是在 BLE
594	 *     起来之后才写的），开机不会回连。
595	 *   - **记录没有、槽位却有地址** → 有东西绕过记录在连，也就是"删了也回来"
596	 *     的形态。修完之后不该出现。
597	 *
598	 * 两个地址都打全，方便和 `sys rec` / `sys found` 逐字节对（RPA 轮换的设备
599	 * 会对不上，见 §3.7）。
600	 */
601	void myvendor_devctl_sensor_link_dump(void)
602	{
603	  myvendor_devctl_sensor_rec_t recs[MYVENDOR_DEVCTL_SENSOR_REC_MAX];
604	  myvendor_sys_sensor_ui_t ui;
605	  size_t n = 0;
606	  uint8_t k;
607	
608	  myvendor_sys_sensor_ui_get(&ui);
609	  (void)myvendor_devctl_sensor_recs_get(recs, MYVENDOR_DEVCTL_SENSOR_REC_MAX,
610	                                        &n);
611	
612	  for (k = 0; k < MYVENDOR_DEVCTL_SENSOR_KIND_N; k++)
613	    {
614	      const myvendor_devctl_sensor_rec_t *rec = NULL;
615	      const myvendor_sys_sensor_slot_t   *slot = NULL;
616	      char ra[24];
617	      char sa[24];
618	      size_t r;
619	      bool slot_have;
620	
621	      for (r = 0; r < n; r++)
622	        {
623	          if (recs[r].kind == k && recs[r].autorc)
624	            {
625	              rec = &recs[r];
626	              break;
627	            }
628	        }
629	
630	      if (k < MYVENDOR_SYS_SENSOR_KIND_N)
631	        {
632	          slot = &ui.slot[k];
633	          slot_have = (slot->addr[0] | slot->addr[1] | slot->addr[2] |
634	                       slot->addr[3] | slot->addr[4] | slot->addr[5]) != 0;
635	        }
636	      else
637	        {
638	          slot_have = false;
639	        }
640	
641	      if (rec == NULL && !slot_have)
642	        {
643	          continue;   /* 干净：既没配对目标，也没在连 */
644	        }
645	
646	      if (rec != NULL)
647	        {
648	          srec_mac_fmt(rec->addr, ra, sizeof(ra));
649	        }
650	      else
651	        {
652	          snprintf(ra, sizeof(ra), "--");
653	        }
654	
655	      if (slot_have)
656	        {
657	          srec_mac_fmt(slot->addr, sa, sizeof(sa));
658	        }
659	      else
660	        {
661	          snprintf(sa, sizeof(sa), "--");
662	        }
663	
664	      printf("sys link %s  rec %s %s  slot %s %s\n", srec_kind_name(k),
665	             rec != NULL ? "*" : "-", ra,
666	             slot == NULL ? "--" :
667	             slot->link == MYVENDOR_SYS_SENSOR_LINK_READY ? "ready" :
668	             slot->link == MYVENDOR_SYS_SENSOR_LINK_CONNECTING ? "conn" : "idle",
669	             sa);
670	
671	      if (rec != NULL && !slot_have)
672	        {
673	          printf("sys link %s  WARN 有回连记录但槽位没武装,开机不会回连\n",
674	                 srec_kind_name(k));
675	        }
676	      else if (rec == NULL && slot_have)
677	        {
678	          printf("sys link %s  WARN 无回连记录却在连,有东西绕过 autorc\n",
679	                 srec_kind_name(k));
680	        }
681	    }
682	}
