722	/**
723	 * @brief 把背光百分比夹到 0～硬件上限。
724	 */
725	static uint8_t clamp_bl(int v)
726	{
727	  uint8_t maxp = BSP_LCD_BL_GetMaxPct();
728	
729	  if (v < 0)
730	    {
731	      return 0;
732	    }
733	
734	  if (maxp > 0 && v > (int)maxp)
735	    {
736	      return maxp;
737	    }
738	
739	  if (v > 100)
740	    {
741	      return 100;
742	    }
743	
744	  return (uint8_t)v;
745	}
