747	/**
748	 * @brief 从 persist 载入策略并 PrefPct；不点亮背光。
749	 *
750	 * 工厂固件不读 persist.usb.mtp / persist.bt.radio，RAM 里直接开 MTP 与手机 BLE，
751	 * 也不回写这两项，避免冲掉产品侧开关。工厂也不弹出手机通知（不写 persist.ui.notif）。
752	 */
753	void myvendor_devctl_load(void)
754	{
755	  int bl;
756	  int sensor;
757	  int notif;
758	  int calls;
759	  int sound;
760	  int autopause;
761	  int eph_auto;
762	  int gnss_rmc;
763	  int grade;
764	  int tz;
765	
766	  /* 先把上次 `ctl log` 的屏蔽位装回去，再干别的：这样后面这一段 load 自己的
767	   * 日志、以及本轮之后才起来的 gnss/ble/diag/UI 线程，都直接按用户的档位走。
768	   *
769	   * `nx_setlogmask()` 会遍历所有已存在的任务一起改，新任务在
770	   * sched/tls/task_initinfo.c 里继承这个全局值 —— 所以晚初始化步骤不用各自
771	   * 再调一次。代价是 bringup 里 storage 之前的十几步（watchdog/vfs/rtc/lcd…）
772	   * 仍用 `CONFIG_SYSLOG_DEFAULT_MASK`：KV 那时还没挂，读不到。
773	   *
774	   * 工厂固件不读：KV 里那份是产品侧调的（产品平时压到 0xf），工厂要的是全开。
775	   * 跟下面 mtp / radio 两项同一个道理。 */
776	
777	  if (myvendor_is_factory())
778	    {
779	      g_log_mask = (uint8_t)MYVENDOR_DEVCTL_LOG_DEFAULT;
780	    }
781	  else
782	    {
783	      g_log_mask = (uint8_t)((uint32_t)persist_get_i32(
784	                      MYVENDOR_DEVCTL_LOG_KEY,
785	                      MYVENDOR_DEVCTL_LOG_DEFAULT) & 0xffu);
786	    }
787	
788	  nx_setlogmask((int)g_log_mask);
789	
790	  bl = persist_get_i32(MYVENDOR_DEVCTL_BL_KEY, (int32_t)MYVENDOR_DEVCTL_BL_DEFAULT);
791	  sensor = persist_get_i32(MYVENDOR_DEVCTL_SENSOR_KEY, 1);
792	  notif = persist_get_i32(MYVENDOR_DEVCTL_NOTIF_KEY, 1);
793	  calls = persist_get_i32(MYVENDOR_DEVCTL_CALLS_KEY, 0);
794	  sound = persist_get_i32(MYVENDOR_DEVCTL_SOUND_KEY, 1);
795	  autopause = persist_get_i32(MYVENDOR_DEVCTL_AUTOPAUSE_KEY, 1);
796	  g_last_ride_m = persist_get_i32(MYVENDOR_DEVCTL_LAST_RIDE_M_KEY, 0);
797	  if (g_last_ride_m < 0)
798	    {
799	      g_last_ride_m = 0;
800	    }
801	
802	  {
803	    int32_t lon_e7 = 0;
804	    int32_t lat_e7 = 0;
805	
806	    if (persist_try_i32(MYVENDOR_DEVCTL_LAST_LON_E7_KEY, &lon_e7) &&
807	        persist_try_i32(MYVENDOR_DEVCTL_LAST_LAT_E7_KEY, &lat_e7) &&
808	        last_pos_ok(lon_e7, lat_e7))
809	      {
810	        g_last_lon_e7 = lon_e7;
811	        g_last_lat_e7 = lat_e7;
812	        g_last_pos_have = true;
813	      }
814	    else
815	      {
816	        g_last_lon_e7 = 0;
817	        g_last_lat_e7 = 0;
818	        g_last_pos_have = false;
819	      }
820	  }
821	  eph_auto = persist_get_i32(MYVENDOR_DEVCTL_EPH_AUTO_KEY, 1);
822	  /* 默认改为 **1：用模组的多普勒速度（RMC SOG）**，不用固件的位置差分滤波。
823	   *
824	   * 依据（2026-09-17 从导出的 TRK gpx 反推）：Δt 干净到最小正好 1.000 s，
825	   * 但位置差分在 1 Hz 下的噪声底就是 ±3 km/h —— 静止时能算出 3.1 km/h，
826	   * 而中位 21.8 km/h 的行程里最大跳到 89.7 km/h（24.9 m/1 s 的位置噪声），
827	   * 再被固件自己的 sanity 判成"异常"置 0（高速下坡那次就是这么归零的）。
828	   * 模组的 SOG 是多普勒测的，静止≈0、骑行平滑，没有这个问题。
829	   * 保留这个开关是为了排查时能切回去对比（App/UI 侧 `bicycle_runtime_set_gnss_solver_rmc()`）。
830	   *
831	   * 注意：**已经存过 0 的机器不吃这个新默认值**（persist 里有旧值），
832	   * 需要在 App/UI 里手动切一次，或者删掉这个 persist key。 */
833	  gnss_rmc = persist_get_i32(MYVENDOR_DEVCTL_GNSS_RMC_KEY, 1);
834	  grade = persist_get_i32(MYVENDOR_DEVCTL_GRADE_KEY, 0);
835	  tz = persist_get_i32(MYVENDOR_DEVCTL_TZ_KEY, MYVENDOR_DEVCTL_TZ_DEFAULT);
836	
837	  g_bl = clamp_bl(bl);
838	  g_sensor = sensor != 0;
839	  g_notif = notif != 0;
840	  g_calls = calls != 0;
841	  g_sound = sound != 0;
842	  g_autopause = autopause != 0;
