1084	/**
1085	 * @brief 按 **MAC** 连接一台扫描到的设备（设备端 UI 点击用）。
1086	 *
1087	 * @details
1088	 * 为什么要有这条：`myvendor_devctl_sensor_connect_kind()` 传的是**扫描表下标**，
1089	 * 而那张表是活的 —— 扫描回调会并发改写它（"更弱的设备被替换"那条规则），
1090	 * 而且**每次用户起扫都会整表清空**。于是"前台显示第 3 项 → 用户点它 →
1091	 * 底层按 idx=3 去查表"这两个时刻之间，只要表被清过或那行被换过，
1092	 * `g_found[idx-1]` 拿到的就是**别的设备、甚至全零地址**。
1093	 *
1094	 * 按 MAC 寻址没有这个问题：MAC 在"显示"那一刻就已经定下来了，之后表怎么变
1095	 * 都指向同一台设备。UI 手上本来就有 MAC（`myvendor_sys_sensor_ui_get()` 的
1096	 * `found[].addr/addr_type`，占用检查那段早就在用了）。
1097	 *
1098	 * 服务侧走的也是已有路径：填 `bind` → `COMPANION_TEST_SENSOR_CONNECT_ADDR`
1099	 * → `ble_sensor_connect_addr()`（与回连记录同一条）。
1100	 *
1101	 * @param addr      6 字节 LE 地址。
1102	 * @param addr_type 地址类型。
1103	 * @param kind      绑到哪个类型槽位（0 HR / 1 CSC / 2 CPS）。
1104	 * @param name      可为 NULL。
1105	 * @return 0 已投递；-EINVAL 参数非法；-ENOTSUP 未编 companion。
1106	 */
1107	int myvendor_devctl_sensor_connect_addr(const uint8_t *addr, uint8_t addr_type,
1108	                                        uint8_t kind, const char *name)
1109	{
1110	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
1111	  struct companion_sensor_bind bind;
1112	
1113	  if (addr == NULL)
1114	    {
1115	      return -EINVAL;
1116	    }
1117	
1118	  memset(&bind, 0, sizeof(bind));
1119	  memcpy(bind.addr, addr, COMPANION_SENSOR_ADDR_LEN);
1120	  bind.addr_type = addr_type;
1121	  bind.kind      = kind;
1122	  if (name != NULL)
1123	    {
1124	      strncpy(bind.name, name, sizeof(bind.name) - 1u);
1125	      bind.name[sizeof(bind.name) - 1u] = '\0';
1126	    }
1127	
1128	  companion_bridge_sensor_cmd_set_bind(&bind);
1129	  companion_bridge_sensor_cmd_post(COMPANION_TEST_SENSOR_CONNECT_ADDR);
1130	  return 0;
1131	#else
1132	  (void)addr;
1133	  (void)addr_type;
1134	  (void)kind;
1135	  (void)name;
1136	  return -ENOTSUP;
1137	#endif
1138	}
