1437	int myvendor_devctl_log_mask_set(uint8_t mask, uint8_t *old)
1438	{
1439	  int prev;
1440	  int ret;
1441	
1442	  ensure_loaded();
1443	
1444	  /* 先改内存再落地：写盘失败也保留本次生效的档位。反过来（先写后改、写失败
1445	   * 就放弃）会让调用方看到"设了却没生效"，比"设了但没记住"更难查。 */
1446	
1447	  prev = nx_setlogmask((int)mask);
1448	  g_log_mask = mask;
1449	
1450	  if (old != NULL)
1451	    {
1452	      *old = (uint8_t)prev;
1453	    }
1454	
1455	  /* 工厂固件不回写：KV 里那份是产品侧调的档位，产测把它改成 0xff 会跟着
1456	   * 产品固件一起带走，产品上就变成刷屏。跟 mtp / radio 同一个理由。 */
1457	  if (myvendor_is_factory())
1458	    {
