1548	int myvendor_devctl_sensor_remember(uint8_t kind, const uint8_t *addr,
1549	                                    uint8_t addr_type, const char *name)
1550	{
1551	  uint8_t i;
1552	  uint8_t idx = 0xffu;
1553	  int ret = 0;
1554	  bool found = false;
1555	  bool dirty = false;
1556	  uint8_t drop_addr[MYVENDOR_DEVCTL_SENSOR_ADDR_LEN];
1557	  uint8_t drop_kind = 0;
1558	  bool have_drop = false;
1559	
1560	  if (kind > MYVENDOR_DEVCTL_SENSOR_KIND_CPS || srec_addr_empty(addr))
1561	    {
1562	      return -EINVAL;
1563	    }
1564	
1565	  memset(drop_addr, 0, sizeof(drop_addr));
1566	  pthread_mutex_lock(&g_srec_lock);
1567	  srec_ensure_locked();
1568	  for (i = 0; i < g_srec_n; i++)
1569	    {
1570	      if (g_srec[i].autorc && g_srec[i].kind == kind &&
1571	          !srec_addr_eq(g_srec[i].addr, addr))
1572	        {
1573	          memcpy(drop_addr, g_srec[i].addr, sizeof(drop_addr));
1574	          drop_kind = g_srec[i].kind;
1575	          have_drop = true;
1576	          break;
1577	        }
1578	    }
1579	
1580	  for (i = 0; i < g_srec_n; i++)
1581	    {
1582	      if (g_srec[i].kind == kind && srec_addr_eq(g_srec[i].addr, addr))
1583	        {
1584	          if (g_srec[i].addr_type != addr_type)
1585	            {
1586	              g_srec[i].addr_type = addr_type;
1587	              dirty = true;
1588	            }
1589	
1590	          if (name != NULL && name[0] != '\0')
1591	            {
1592	              char tmp[MYVENDOR_DEVCTL_SENSOR_NAME_MAX];
1593	
1594	              srec_name_copy(tmp, sizeof(tmp), name);
1595	              if (memcmp(g_srec[i].name, tmp, sizeof(tmp)) != 0)
1596	                {
1597	                  memcpy(g_srec[i].name, tmp, sizeof(tmp));
1598	                  dirty = true;
1599	                }
1600	            }
1601	
1602	          found = true;
1603	          idx = i;
1604	          break;
1605	        }
1606	    }
1607	
1608	  if (!found)
1609	    {
1610	      if (g_srec_n >= MYVENDOR_DEVCTL_SENSOR_REC_MAX)
1611	        {
1612	          uint8_t drop = 0xffu;
1613	
1614	          for (i = 0; i < g_srec_n; i++)
1615	            {
1616	              if (!g_srec[i].autorc)
1617	                {
1618	                  drop = i;
1619	                  break;
1620	                }
1621	            }
1622	
1623	          if (drop == 0xffu)
1624	            {
1625	              drop = 0;
1626	            }
1627	
1628	          memmove(&g_srec[drop], &g_srec[drop + 1u],
1629	                  (size_t)(g_srec_n - drop - 1u) * sizeof(g_srec[0]));
1630	          g_srec_n--;
1631	        }
1632	
1633	      idx = g_srec_n;
1634	      memset(&g_srec[idx], 0, sizeof(g_srec[0]));
1635	      g_srec[idx].kind = kind;
1636	      g_srec[idx].addr_type = addr_type;
1637	      memcpy(g_srec[idx].addr, addr, MYVENDOR_DEVCTL_SENSOR_ADDR_LEN);
1638	      srec_name_copy(g_srec[idx].name, sizeof(g_srec[idx].name), name);
1639	      g_srec_n++;
1640	      dirty = true;
1641	    }
1642	
1643	  if (idx < g_srec_n && !g_srec[idx].autorc)
1644	    {
1645	      dirty = true;
1646	    }
1647	
1648	  if (!dirty)
1649	    {
1650	      pthread_mutex_unlock(&g_srec_lock);
1651	      return 0;
1652	    }
1653	
1654	  for (i = 0; i < g_srec_n; i++)
1655	    {
1656	      if (g_srec[i].kind == kind)
1657	        {
1658	          g_srec[i].autorc = (i == idx);
1659	        }
1660	    }
1661	
1662	  ret = srec_save_locked();
1663	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
1664	  /* 已在 READY，不再 post CONNECT。只清掉上一台的 want_link。 */
1665	  if (ret == 0 && have_drop)
1666	    {
1667	      srec_post_clear_locked(drop_addr, drop_kind);
1668	    }
1669	#else
1670	  (void)have_drop;
1671	  (void)drop_kind;
1672	#endif
1673	  pthread_mutex_unlock(&g_srec_lock);
1674	  return ret;
1675	}
