1808	int myvendor_devctl_waypoints_load(const char *path,
1809	                                   myvendor_devctl_favorite_t *out,
1810	                                   size_t cap, size_t *count)
1811	{
1812	  FILE *fp;
1813	  char line[160];
1814	  size_t n = 0;
1815	
1816	  if (path == NULL || path[0] == '\0' || out == NULL || cap == 0 ||
1817	      count == NULL)
1818	    {
1819	      return -EINVAL;
1820	    }
1821	
1822	  *count = 0;
1823	  fp = fopen(path, "r");
1824	  if (fp == NULL)
1825	    {
1826	      return errno == ENOENT ? 0 : -errno;
1827	    }
1828	
1829	  while (fgets(line, sizeof(line), fp) != NULL)
1830	    {
1831	      char *name;
1832	      char *lat_text;
1833	      char *lon_text;
1834	      char *extra;
1835	      char *save = NULL;
1836	      size_t len = strlen(line);
1837	      double lat;
1838	      double lon;
1839	
1840	      if (len > 0 && line[len - 1] == '\n')
1841	        {
1842	          line[--len] = '\0';
1843	        }
1844	      if (len > 0 && line[len - 1] == '\r')
1845	        {
1846	          line[--len] = '\0';
1847	        }
1848	      if (len == 0)
1849	        {
1850	          continue;
1851	        }
1852	
1853	      name = strtok_r(line, "\t", &save);
1854	      lat_text = strtok_r(NULL, "\t", &save);
1855	      lon_text = strtok_r(NULL, "\t", &save);
1856	      extra = strtok_r(NULL, "\t", &save);
1857	      if (name == NULL || name[0] == '\0' ||
1858	          strlen(name) >= MYVENDOR_DEVCTL_FAVORITE_NAME_MAX ||
1859	          lat_text == NULL || lon_text == NULL || extra != NULL ||
1860	          !favorite_coord_parse(lat_text, -90.0, 90.0, &lat) ||
1861	          !favorite_coord_parse(lon_text, -180.0, 180.0, &lon))
1862	        {
1863	          fclose(fp);
1864	          return -EINVAL;
1865	        }
1866	      if (n >= cap)
1867	        {
1868	          fclose(fp);
1869	          return -E2BIG;
1870	        }
1871	
1872	      snprintf(out[n].name, sizeof(out[n].name), "%s", name);
1873	      out[n].latitude = lat;
1874	      out[n].longitude = lon;
1875	      n++;
1876	    }
1877	
1878	  if (ferror(fp))
1879	    {
1880	      int err = errno != 0 ? errno : EIO;
1881	
1882	      fclose(fp);
1883	      return -err;
1884	    }
1885	
1886	  fclose(fp);
1887	  *count = n;
1888	  return 0;
1889	}
