1941	  cal = mv - MYVENDOR_DEVCTL_BAT_FULL_MARGIN_MV;
1942	  if (!bat_full_mv_ok(cal))
1943	    {
1944	      return;
1945	    }
1946	
1947	  if (!g_bat_full_have)
1948	    {
1949	      int32_t stored;
1950	
1951	      if (persist_try_i32(MYVENDOR_DEVCTL_BAT_FULL_KEY, &stored) &&
1952	          bat_full_mv_ok((int)stored))
1953	        {
1954	          g_bat_full_mv = (int)stored;
1955	          g_bat_full_have = true;
1956	        }
1957	    }
1958	
1959	  if (g_bat_full_have)
1960	    {
