73	/**
74	 * @brief 解析 on/1 或 off/0。
75	 * @return 0 成功，-EINVAL 非法。
76	 */
77	static int parse_onoff(const char *s, bool *on)
78	{
79	  if (s == NULL)
80	    {
81	      return -EINVAL;
82	    }
83	
84	  if (strcmp(s, "on") == 0 || strcmp(s, "1") == 0)
85	    {
86	      *on = true;
87	      return 0;
88	    }
89	
90	  if (strcmp(s, "off") == 0 || strcmp(s, "0") == 0)
91	    {
92	      *on = false;
93	      return 0;
94	    }
95	
96	  return -EINVAL;
97	}
