350	static bool favorite_coord_parse(const char *text, double min, double max,
351	                                 double *value)
352	{
353	  char *end = NULL;
354	  double v;
355	
356	  if (text == NULL || value == NULL)
357	    {
358	      return false;
359	    }
360	
361	  errno = 0;
362	  v = strtod(text, &end);
363	  if (errno != 0 || end == text || end == NULL || *end != '\0' ||
364	      !isfinite(v) || v < min || v > max)
365	    {
366	      return false;
367	    }
368	
369	  *value = v;
370	  return true;
371	}
