373	static int favorite_load(struct ctl_favorite_s *items, size_t cap,
374	                         size_t *count)
375	{
376	  FILE *fp;
377	  char line[160];
378	  size_t n = 0;
379	
380	  if (items == NULL || count == NULL)
381	    {
382	      return -EINVAL;
383	    }
384	
385	  *count = 0;
386	  fp = fopen(CTL_FAV_PATH, "r");
387	  if (fp == NULL)
388	    {
389	      return errno == ENOENT ? 0 : -errno;
390	    }
391	
392	  while (fgets(line, sizeof(line), fp) != NULL)
393	    {
394	      char *name;
395	      char *lat_text;
396	      char *lon_text;
397	      char *extra;
398	      char *save = NULL;
399	      size_t len = strlen(line);
400	      double lat;
401	      double lon;
402	
403	      if (len > 0 && line[len - 1] == '\n')
404	        {
405	          line[--len] = '\0';
406	        }
407	      if (len > 0 && line[len - 1] == '\r')
408	        {
409	          line[--len] = '\0';
410	        }
411	      if (len == 0)
412	        {
413	          continue;
414	        }
415	
416	      name = strtok_r(line, "\t", &save);
417	      lat_text = strtok_r(NULL, "\t", &save);
418	      lon_text = strtok_r(NULL, "\t", &save);
419	      extra = strtok_r(NULL, "\t", &save);
420	      if (!favorite_name_valid(name) || lat_text == NULL || lon_text == NULL ||
421	          extra != NULL ||
422	          !favorite_coord_parse(lat_text, -90.0, 90.0, &lat) ||
423	          !favorite_coord_parse(lon_text, -180.0, 180.0, &lon))
424	        {
425	          fclose(fp);
426	          return -EINVAL;
427	        }
428	      if (n >= cap)
429	        {
430	          fclose(fp);
431	          return -E2BIG;
432	        }
433	
434	      snprintf(items[n].name, sizeof(items[n].name), "%s", name);
435	      items[n].latitude = lat;
436	      items[n].longitude = lon;
437	      n++;
438	    }
439	
440	  if (ferror(fp))
441	    {
442	      int err = errno != 0 ? errno : EIO;
443	
444	      fclose(fp);
445	      return -err;
446	    }
447	
448	  fclose(fp);
449	  *count = n;
450	  return 0;
451	}
