453	static int favorite_save(const struct ctl_favorite_s *items, size_t count)
454	{
455	  FILE *fp;
456	  size_t i;
457	  int ret = 0;
458	
459	  fp = fopen(CTL_FAV_TMP_PATH, "w");
460	  if (fp == NULL)
461	    {
462	      return -errno;
463	    }
464	
465	  for (i = 0; i < count; i++)
466	    {
467	      if (fprintf(fp, "%s\t%.7f\t%.7f\n", items[i].name,
468	                  items[i].latitude, items[i].longitude) < 0)
469	        {
470	          ret = -(errno != 0 ? errno : EIO);
471	          break;
472	        }
473	    }
474	
475	  if (ret == 0 && fflush(fp) != 0)
476	    {
477	      ret = -errno;
478	    }
479	  if (ret == 0 && fsync(fileno(fp)) != 0)
480	    {
481	      ret = -errno;
482	    }
483	  if (fclose(fp) != 0 && ret == 0)
484	    {
485	      ret = -errno;
486	    }
487	
488	  if (ret == 0 && rename(CTL_FAV_TMP_PATH, CTL_FAV_PATH) != 0)
489	    {
490	      ret = -errno;
491	    }
492	  if (ret != 0)
493	    {
494	      unlink(CTL_FAV_TMP_PATH);
495	    }
496	
497	  return ret;
498	}
