920	    sf32lb_dvfs_gov_stat(&age_ms, &runs);
921	    printf("  dvfs    gov     last run %u ms ago, %u runs, %u recoveries\n",
922	           (unsigned)age_ms, (unsigned)runs,
923	           (unsigned)sf32lb_dvfs_gov_recoveries());
924	  }
