928	/**
929	 * @brief `ctl log [level]`：全系统 syslog 屏蔽位，省略则打印当前值。
930	 *
931	 * @details
932	 * 改的是 `g_syslog_mask`，并且 `nx_setlogmask()` 会**遍历所有已存在的任务**
933	 * 一起改（drivers/syslog/setlogmask.c 的 task_syslogmask），新任务在
934	 * sched/tls/task_initinfo.c 里继承这个全局值 —— 所以立刻全系统生效、
935	 * 不需要重编译，也能运行时随时调回来。
936	 *
937	 * **屏蔽的是 syslog 输出**（带 `[  INFO]` / `[  WARN]` 前缀的那些，闸门在
938	 * libs/libc/syslog/lib_syslog.c 的 `ta_syslog_mask & LOG_MASK(priority)`）。
939	 * `printf` 不过 syslog（NSH 提示符、test_app、ctl 自己的输出），**不受影响** ——
940	 * 所以这个开关能压掉驱动/内核的刷屏，但压不掉应用 printf。
941	 *
942	 * **档位落 KV**（`persist.log.mask`，落在 `myvendor_devctl_load()` 里恢复）：
943	 * 以前每次开机都要重敲一遍。写盘失败只警告，不回滚当前档位。
944	 *
945	 * 建议值：平时 `err`（只留错误），查问题前 `info` 或 `all`。
946	 */
947	static int cmd_log(int argc, char *argv[])
948	{
949	  /* POSIX 优先级：数值越小越严重，LOG_UPTO(p) 保留 0..p。 */
950	  static const char * const names[] =
951	  {
952	    "EMERG", "ALERT", "CRIT", "ERROR", "WARN", "NOTICE", "INFO", "DEBUG"
953	  };
954	
955	  uint8_t mask;
956	  uint8_t old;
957	  int want = -1;
958	  int ret;
959	  int i;
960	
961	  if (argc < 2)
962	    {
963	      mask = myvendor_devctl_log_mask_get();
964	      printf("syslog mask 0x%02x  (%s)\n", (unsigned)mask,
965	             MYVENDOR_DEVCTL_LOG_KEY);
966	      for (i = 0; i < 8; i++)
967	        {
968	          printf("  %-6s %s\n", names[i],
969	                 (mask & LOG_MASK(i)) != 0 ? "on" : "off");
970	        }
971	
972	      return 0;
973	    }
974	
975	  if (strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "help") == 0)
976	    {
977	      printf("ctl log                 print current syslog mask\n");
978	      printf("ctl log err|warn|notice|info|all   keep levels up to this\n");
979	      printf("ctl log silent          only EMERG\n");
980	      printf("ctl log 0x1f            set raw mask\n");
981	      printf("  saved as %s, restored on boot\n", MYVENDOR_DEVCTL_LOG_KEY);
982	      printf("  (printf is NOT syslog; NSH/apps keep printing)\n");
983	      return 0;
984	    }
985	
986	  if (strcmp(argv[1], "err") == 0 || strcmp(argv[1], "error") == 0)
987	    {
988	      want = LOG_UPTO(LOG_ERR);
989	    }
990	  else if (strcmp(argv[1], "warn") == 0 || strcmp(argv[1], "warning") == 0)
991	    {
992	      want = LOG_UPTO(LOG_WARNING);
993	    }
994	  else if (strcmp(argv[1], "notice") == 0)
995	    {
996	      want = LOG_UPTO(LOG_NOTICE);
997	    }
998	  else if (strcmp(argv[1], "info") == 0)
999	    {
1000	      want = LOG_UPTO(LOG_INFO);
1001	    }
1002	  else if (strcmp(argv[1], "all") == 0 || strcmp(argv[1], "debug") == 0)
1003	    {
1004	      want = 0xff;
1005	    }
1006	  else if (strcmp(argv[1], "silent") == 0 || strcmp(argv[1], "none") == 0)
1007	    {
1008	      want = LOG_MASK(LOG_EMERG);
1009	    }
1010	  else
1011	    {
1012	      char *end = NULL;
1013	      unsigned long raw = strtoul(argv[1], &end, 0);
1014	
1015	      if (end == argv[1] || *end != '\0' || raw > 0xff)
1016	        {
1017	          fprintf(stderr, "ctl log: unknown level '%s'\n", argv[1]);
1018	          return EXIT_FAILURE;
1019	        }
1020	
1021	      want = (int)raw;
1022	    }
1023	
1024	  mask = (uint8_t)want;
1025	  ret = myvendor_devctl_log_mask_set(mask, &old);
1026	
1027	  printf("syslog mask 0x%02x -> 0x%02x\n", (unsigned)old, (unsigned)mask);
1028	  for (i = 0; i < 8; i++)
1029	    {
1030	      printf("  %-6s %s\n", names[i],
1031	             (mask & LOG_MASK(i)) != 0 ? "on" : "off");
1032	    }
1033	
1034	  if (ret < 0)
1035	    {
1036	      /* 档位已经生效，只是没写进 KV：说清楚，免得下次开机发现"又回去了"。 */
1037	      printf("  WARN  %s write failed (%d), lost after reboot\n",
1038	             MYVENDOR_DEVCTL_LOG_KEY, ret);
1039	    }
1040	
1041	  return 0;
1042	}
