1172	/**
1173	 * @brief 裸块读写自检：不进 LFS、绕过判死闸门。
1174	 *
1175	 * @details 存在的理由：卡一旦判死，**LFS 层就不下发 I/O 了**，常规读写全部
1176	 *          立刻返回 -EIO，于是没法再判断"卡到底还响不响应"。这条命令刻意
1177	 *          绕开闸门，是判死之后唯一还能直接验卡的手段。逐块报时间也是必要的：
1178	 *          坏页/磨损页的典型特征是**某一块明显慢或直接失败**，只看总结果分辨不出来。
1179	 *
1180	 * @note 它同时证伪过一个假设，别再捡回来：曾经怀疑"首次失败总是落在 LFS 块 194
1181	 *       （偏移 0xC2000）"，用 `ctl sd read 200c2000 8` 实测 8 个块全部正常
1182	 *       （约 880 µs），而另一次记录的首次失败偏移是 0x20000000（块 0）。
1183	 *       "卡在某个坏块上"这个方向因此被排除，真正的原因是控制器卡在 CMD_BUSY
1184	 *       （见 docs/sd_recovery.md）。本命令保留为通用的验卡工具，不再代表那个假设。
1185	 */
1186	static int cmd_sd(int argc, char **argv)
1187	{
1188	  uint64_t off;
1189	  uint32_t n;
1190	
1191	  if (argc >= 3 && strcmp(argv[1], "read") == 0)
1192	    {
1193	      off = strtoull(argv[2], NULL, 16);
1194	      n = (argc >= 4) ? (uint32_t)strtoul(argv[3], NULL, 10) : 1u;
1195	      if (n == 0u || n > 256u)
1196	        {
1197	          n = 1u;
1198	        }
1199	
1200	      return sf32lb_sd_raw_read(off, n);
1201	    }
1202	
1203	  if (argc >= 3 && strcmp(argv[1], "write") == 0)
1204	    {
1205	      off = strtoull(argv[2], NULL, 16);
1206	      n = (argc >= 4) ? (uint32_t)strtoul(argv[3], NULL, 10) : 1u;
1207	      if (n == 0u || n > 256u)
1208	        {
1209	          n = 1u;
1210	        }
1211	
1212	      /* 写目标只有驱动器尾部那 1 MiB 是安全的（唯一不属于任何文件系统的
1213	       * 区域）；驱动内部还有一道不可绕过的闸门，这里只是提前给用法。 */
1214	      return sf32lb_sd_raw_write(off, n);
1215	    }
1216	
1217	  printf("ctl sd read  <hex_off> [n]    raw 512B block read, per-block timing\n");
1218	  printf("ctl sd write <hex_off> [n]    0xFF program + readback verify\n");
1219	  printf("  both bypass the dead gate on purpose, so they work on a dead card\n");
1220	  printf("  e.g. ctl sd read  200c2000 8        (LFS block 194)\n");
1221	  printf("       ctl sd write <card_size-4096> 32   (sacrificial tail ONLY)\n");
1222	  return -EINVAL;
1223	}
