55	static bool wait_for_lcddev(const char * path, int timeout_ms)
56	{
57	    const int step_ms = 100;
58	    int elapsed = 0;
59	
60	    while (elapsed < timeout_ms) {
61	        int fd = open(path, O_RDWR);
62	        if (fd >= 0) {
63	            close(fd);
64	            LV_LOG_USER("lcd ready: %s (%d ms)", path, elapsed);
65	            return true;
66	        }
67	        usleep(step_ms * 1000);
68	        elapsed += step_ms;
69	    }
70	
71	    LV_LOG_ERROR("lcd not ready: %s (waited %d ms, errno=%d)",
72	        path, timeout_ms, errno);
73	    return false;
74	}
