87	int main(int argc, char * argv[])
88	{
89	    (void)argc;
90	    (void)argv;
91	
92	    map_page_t * page;
93	    bicycle_mtp_ui_t mtp_ui;
94	
95	    if (lv_is_initialized()) {
96	        LV_LOG_ERROR("LVGL already initialized");
97	        return -1;
98	    }
99	
100	    lv_init();
101	
102	    if (!wait_for_lcddev(BICYCLE_LCD_PATH, BICYCLE_LCD_WAIT_MS)) {
103	        return 1;
104	    }
105	
106	    lv_nuttx_dsc_t info;
107	    lv_nuttx_result_t result;
108	    lv_nuttx_dsc_init(&info);
109	    info.fb_path = BICYCLE_LCD_PATH;
110	    lv_nuttx_init(&info, &result);
111	
112	    if (result.disp == NULL) {
113	        LV_LOG_ERROR("display init failed");
114	        return 1;
115	    }
116	
117	    {
118	        lv_obj_t * scr = lv_display_get_screen_active(result.disp);
119	        lv_timer_t * refr;
120	
121	        lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
122	        lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
123	        /* Keep 2SFBL pixels on the panel until splash is ready. */
124	        lv_display_enable_invalidation(result.disp, false);
125	        refr = lv_display_get_refr_timer(result.disp);
126	        if (refr) {
127	            lv_timer_pause(refr);
128	        }
129	    }
130	
131	    lv_display_set_antialiasing(result.disp, true);
132	
133	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
134	    if (myvendor_lcd_disp_register_done_cb(bicycle_lcd_flush_done, result.disp) < 0) {
135	        LV_LOG_ERROR("lcd flush callback failed");
136	        return 1;
137	    }
138	#endif
139	
140	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
141	    bicycle_inval_probe_init(result.disp);
142	#endif
143	
144	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
145	    bicycle_handler_stat_init();
146	#endif
147	    bicycle_c_debug_init();
148	
149	    lv_port_buttons_init();
150	
151	    lvgl_page_init();
152	
153	    if (lvgl_page_open_boot_sequence() != 0) {
154	        LV_LOG_ERROR("lvgl_page_open_boot_sequence failed");
155	        return 1;
156	    }
157	
158	    if (!myvendor_is_factory()) {
159	        startup_page_sync_boot();
160	    }
161	
162	    /* Splash / factory page use compiled-in helm fonts. Paint before TTF / MTP / vmap. */
163	    lv_display_enable_invalidation(result.disp, true);
164	    {
165	        lv_timer_t * refr = lv_display_get_refr_timer(result.disp);
166	        lv_obj_t * scr = lv_display_get_screen_active(result.disp);
167	
168	        if (refr) {
169	            lv_timer_resume(refr);
170	        }
171	        lv_obj_invalidate(scr);
172	        lv_obj_update_layout(scr);
173	    }
174	    lv_refr_now(result.disp);
175	
176	    page = lvgl_page_map();
177	    if (myvendor_is_factory()) {
178	        LV_LOG_USER("bicycle: factory page (bitmap fonts, no TTF)");
179	    } else if (!page) {
180	        LV_LOG_USER("bicycle: splash active, LiveMap loads under Startup");
181	    }
182	
183	    myvendor_mtp_owner_reset();
184	    if (myvendor_mtp_init() != 0) {
185	        LV_LOG_WARN("MTP service init failed (MTP disabled?)");
186	    } else if (myvendor_mtp_transfer_begin() != 0) {
187	        LV_LOG_WARN("MTP transfer_begin deferred until host ENUM");
188	    }
189	
190	    bicycle_mtp_ui_init(&mtp_ui);
191	    if (myvendor_is_factory()) {
192	        bicycle_ride_gpx_salvage_dir();
193	    }
194	    lvgl_page_set_app_started(true);
195	
196	    LV_LOG_USER(myvendor_is_factory()
197	                ? "bicycle started (factory page + MTP + BLE)"
198	                : "bicycle started (lvgl_page + vmap + MTP)");
199	    bicycle_ui_ctl_ready();
200	    bicycle_ui_ctl_sync_state();
201	    if (myvendor_is_factory()) {
202	        myvendor_gnss_ui_ready();
203	#ifdef CONFIG_MYVENDOR_BLE_COMPANION_AUTOSTART
204	        board_ble_companion_start_after_ui();
205	#endif
206	    }
207	    sf32lb_dvfs_hold(SF32LB_DVFS_HOLD_AWAKE);
208	    sf32lb_dvfs_release(SF32LB_DVFS_HOLD_BOOT);
209	
210	#ifndef CONFIG_DISABLE_PTHREAD
211	    pthread_setname_np(pthread_self(), "bicycle_ui");
212	#endif
213	
214	    while (1) {
215	        myvendor_watchdog_ui_beat();
216	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
217	        bicycle_handler_stat_begin();
218	#endif
219	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
220	        myvendor_lcd_disp_poll_recover_ui();
221	#endif
222	        if (myvendor_is_factory()) {
223	#ifdef CONFIG_MYVENDOR_FACTORY_MODE
224	            factory_page_poll_active();
225	#endif
226	        } else {
227	            bicycle_mtp_ui_run(&mtp_ui);
228	            if (lvgl_page_is_usb_transfer()) {
229	                usb_transfer_page_poll_active();
230	            }
231	        }
232	        page = lvgl_page_map();
233	        bicycle_ui_ctl_poll(page);
234	        {
235	#if MYVENDOR_LVGL_STALL_LOG
236	            uint32_t t0 = lv_tick_get();
237	#endif
238	            uint32_t idle = lv_timer_handler();
239	#if MYVENDOR_LVGL_STALL_LOG
240	            uint32_t busy = lv_tick_elaps(t0);
241	
242	            if (busy >= 50u) {
243	                LVGL_STALL("lv_timer_handler %ums idle_ret=%u",
244	                    (unsigned)busy, (unsigned)idle);
245	            }
246	#endif
247	
248	#if defined(CONFIG_MYVENDOR_LCD_DISP) && CONFIG_MYVENDOR_LCD_DISP
249	            myvendor_lcd_disp_poll_recover_ui();
250	#endif
251	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
252	            bicycle_handler_stat_after_handler(idle, BICYCLE_LOOP_SLEEP_MS);
253	            bicycle_handler_stat_usleep_begin();
254	#endif
255	            bicycle_c_debug_loop(idle);
256	        }
257	        if (page && !lvgl_page_is_usb_transfer()) {
258	            map_page_debug_snap(page);
259	        }
260	        {
261	            uint32_t sleep_ms = BICYCLE_LOOP_SLEEP_MS;
262	
263	            if (myvendor_bicycle_ctl_pending()) {
264	                sleep_ms = 0;
265	            }
266	
267	            usleep((useconds_t)sleep_ms * 1000u);
268	        }
269	#if defined(CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT) && CONFIG_MYVENDOR_BICYCLE_HANDLER_STAT
270	        bicycle_handler_stat_usleep_end();
271	#endif
272	    }
273	
274	    myvendor_mtp_deinit();
275	    lv_nuttx_deinit(&result);
276	    lv_deinit();
277	    return 0;
278	}
