{
    unsigned hz;

    if (period_ms == 0) {
        return 1;
    }

    hz = (1000u + period_ms / 2u) / period_ms;
    if (hz < 1u) {
        hz = 1u;
    } else if (hz > 99u) {
        hz = 99u;
    }

    return (uint8_t)hz;
}

