201	 * @param op 操作码。
202	 * @param arg 参数字符串；可为 NULL。
203	 * @return 0 成功；-EINVAL 非法 op；-ENODEV UI 未就绪；-ENOMEM 队列未就绪；-ENOSPC 队列满。
204	 */
205	int myvendor_bicycle_ctl_post(myvendor_bicycle_ctl_op_t op, const char * arg)
206	{
207	    myvendor_bicycle_ctl_msg_t msg;
208	
209	    myvendor_bicycle_ctl_init_once();
210	
211	    if (op <= MYVENDOR_BICYCLE_CTL_OP_NONE ||
212	        op > MYVENDOR_BICYCLE_CTL_OP_IDLE_STAY) {
213	        return -EINVAL;
214	    }
215	
216	    if (!myvendor_bicycle_ctl_ui_alive()) {
217	        return -ENODEV;
218	    }
219	
220	    if (myvendor_bicycle_ctl_queue() == NULL) {
221	        return -ENOMEM;
222	    }
223	
224	    memset(&msg, 0, sizeof(msg));
225	    msg.op = (uint8_t)op;
226	    myvendor_bicycle_ctl_copy_arg(msg.arg, arg);
227	
228	    pthread_mutex_lock(&g_bicycle_ctl.lock);
229	
230	    if (g_bicycle_ctl.q_count >= MYVENDOR_BICYCLE_CTL_QUEUE_DEPTH) {
231	        pthread_mutex_unlock(&g_bicycle_ctl.lock);
232	        return -ENOSPC;
233	    }
234	
235	    g_bicycle_ctl.queue[g_bicycle_ctl.q_tail] = msg;
236	    g_bicycle_ctl.q_tail =
237	        (g_bicycle_ctl.q_tail + 1u) % MYVENDOR_BICYCLE_CTL_QUEUE_DEPTH;
238	    g_bicycle_ctl.q_count++;
239	
240	    pthread_mutex_unlock(&g_bicycle_ctl.lock);
241	    return 0;
242	}
