17	
18	struct fw_cand
19	{
20	  char     name[MYVENDOR_FW_SLOT_NAME_MAX];
21	  uint32_t ver[3];
22	  uint32_t mtime;
23	};
24	
25	static int name_is_bin(const char *name)
26	{
27	  size_t n;
28	
29	  if (name == NULL)
30	    {
31	      return 0;
32	    }
33	
34	  n = strlen(name);
35	  if (n < 5 || n >= MYVENDOR_FW_SLOT_NAME_MAX)
36	    {
37	      return 0;
38	    }
39	
40	  return name[n - 4] == '.' &&
41	         (name[n - 3] == 'b' || name[n - 3] == 'B') &&
42	         (name[n - 2] == 'i' || name[n - 2] == 'I') &&
43	         (name[n - 1] == 'n' || name[n - 1] == 'N');
44	}
45	
46	static void parse_ver_name(const char *name, uint32_t ver[3])
47	{
48	  const char *p = name;
49	  unsigned i;
50	
51	  ver[0] = ver[1] = ver[2] = 0;
52	  if (*p == 'v' || *p == 'V')
53	    {
54	      p++;
55	    }
56	
57	  for (i = 0; i < 3; i++)
58	    {
59	      uint32_t v = 0;
60	
61	      if (*p < '0' || *p > '9')
62	        {
63	          break;
64	        }
65	
66	      while (*p >= '0' && *p <= '9')
67	        {
68	          v = v * 10u + (uint32_t)(*p - '0');
69	          p++;
70	        }
71	
72	      ver[i] = v;
73	      if (*p != '.')
74	        {
75	          break;
76	        }
77	
78	      p++;
79	    }
80	}
81	
82	static int cand_newer(const struct fw_cand *a, const struct fw_cand *b)
83	{
84	  unsigned i;
85	
86	  for (i = 0; i < 3; i++)
87	    {
88	      if (a->ver[i] != b->ver[i])
89	        {
90	          return a->ver[i] > b->ver[i];
91	        }
92	    }
93	
94	  if (a->mtime != b->mtime)
95	    {
96	      return a->mtime > b->mtime;
97	    }
98	
99	  return strcmp(a->name, b->name) > 0;
100	}
101	
102	static void cand_insert(struct fw_cand *cands, unsigned *n, unsigned max,
103	                        const struct fw_cand *in)
104	{
105	  unsigned i;
106	  unsigned j;
107	
108	  for (i = 0; i < *n; i++)
109	    {
110	      if (cand_newer(in, &cands[i]))
111	        {
112	          break;
113	        }
114	    }
115	
116	  if (*n < max)
117	    {
118	      j = *n;
119	      (*n)++;
120	    }
121	  else if (i >= max)
122	    {
123	      return;
124	    }
125	  else
126	    {
127	      j = max - 1u;
128	    }
129	
130	  while (j > i)
131	    {
132	      cands[j] = cands[j - 1u];
133	      j--;
134	    }
135	
136	  cands[i] = *in;
137	}
138	
139	static unsigned scan_bins(struct fw_cand *cands, unsigned maxn)
140	{
141	  DIR *dir;
142	  struct dirent *de;
143	  unsigned n = 0;
144	
145	  dir = opendir(MYVENDOR_FW_SLOT_DIR);
146	  if (dir == NULL)
147	    {
148	      return 0;
149	    }
150	
151	  while ((de = readdir(dir)) != NULL)
152	    {
153	      char path[sizeof(MYVENDOR_FW_SLOT_DIR) + MYVENDOR_FW_SLOT_NAME_MAX];
154	      struct stat st;
155	      struct fw_cand in;
156	
157	      if (!name_is_bin(de->d_name))
158	        {
159	          continue;
160	        }
161	
162	      memset(&in, 0, sizeof(in));
163	      strncpy(in.name, de->d_name, sizeof(in.name) - 1u);
164	      parse_ver_name(in.name, in.ver);
165	      snprintf(path, sizeof(path), "%s/%s", MYVENDOR_FW_SLOT_DIR, in.name);
166	      if (stat(path, &st) == 0)
167	        {
168	          in.mtime = (uint32_t)st.st_mtime;
169	        }
170	
171	      cand_insert(cands, &n, maxn, &in);
172	    }
173	
174	  closedir(dir);
175	  return n;
176	}
