178	static void unlink_sidecar(const char *bin_name)
179	{
180	  char path[sizeof(MYVENDOR_FW_SLOT_DIR) + MYVENDOR_FW_SLOT_NAME_MAX];
181	  char txt[MYVENDOR_FW_SLOT_NAME_MAX];
182	  size_t n;
183	
184	  n = strlen(bin_name);
185	  if (n < 5 || n >= sizeof(txt))
186	    {
187	      return;
188	    }
189	
190	  memcpy(txt, bin_name, n - 4u);
191	  memcpy(txt + n - 4u, ".txt", 5);
192	  snprintf(path, sizeof(path), "%s/%s", MYVENDOR_FW_SLOT_DIR, txt);
193	  (void)unlink(path);
194	}
195	
196	static int unlink_bin(const char *name)
197	{
198	  char path[sizeof(MYVENDOR_FW_SLOT_DIR) + MYVENDOR_FW_SLOT_NAME_MAX];
199	  int ret;
200	
201	  snprintf(path, sizeof(path), "%s/%s", MYVENDOR_FW_SLOT_DIR, name);
202	  ret = unlink(path);
203	  if (ret == 0)
204	    {
205	      unlink_sidecar(name);
206	      syslog(LOG_INFO, "fw_slot: removed %s\n", name);
207	    }
208	
209	  return ret;
210	}
