212	unsigned myvendor_fw_slot_list(struct myvendor_fw_slot_info *out,
213	                               unsigned maxn)
214	{
215	  struct fw_cand cands[MYVENDOR_FW_SLOT_SCAN_MAX];
216	  unsigned n;
217	  unsigned i;
218	
219	  n = scan_bins(cands, MYVENDOR_FW_SLOT_SCAN_MAX);
220	  if (out == NULL || maxn == 0)
221	    {
222	      return n;
223	    }
224	
225	  if (n > maxn)
226	    {
227	      n = maxn;
228	    }
229	
