231	    {
232	      memset(&out[i], 0, sizeof(out[i]));
233	      strncpy(out[i].name, cands[i].name, sizeof(out[i].name) - 1u);
234	      memcpy(out[i].ver, cands[i].ver, sizeof(out[i].ver));
235	    }
236	
237	  return n;
238	}
