240	int myvendor_fw_slot_prune(void)
241	{
242	  int removed = 0;
243	  unsigned first = 0;
244	
245	  for (;;)
246	    {
247	      DIR *dir;
248	      struct dirent *de;
249	      struct fw_cand oldest;
250	      unsigned count = 0;
251	      int have = 0;
252	
253	      dir = opendir(MYVENDOR_FW_SLOT_DIR);
254	      if (dir == NULL)
255	        {
256	          return removed;
257	        }
258	
259	      memset(&oldest, 0, sizeof(oldest));
260	      while ((de = readdir(dir)) != NULL)
261	        {
262	          char path[sizeof(MYVENDOR_FW_SLOT_DIR) + MYVENDOR_FW_SLOT_NAME_MAX];
263	          struct stat st;
264	          struct fw_cand in;
265	
266	          if (!name_is_bin(de->d_name))
267	            {
268	              continue;
269	            }
270	
271	          memset(&in, 0, sizeof(in));
272	          strncpy(in.name, de->d_name, sizeof(in.name) - 1u);
273	          parse_ver_name(in.name, in.ver);
274	          snprintf(path, sizeof(path), "%s/%s", MYVENDOR_FW_SLOT_DIR, in.name);
275	          if (stat(path, &st) == 0)
276	            {
277	              in.mtime = (uint32_t)st.st_mtime;
278	            }
279	
280	          count++;
281	          if (!have || cand_newer(&oldest, &in))
282	            {
283	              oldest = in;
284	              have = 1;
285	            }
286	        }
287	
288	      closedir(dir);
289	
290	      if (first == 0)
291	        {
292	          first = count;
293	          if (count > MYVENDOR_FW_SLOT_KEEP)
294	            {
295	              syslog(LOG_INFO, "fw_slot: prune %u -> %u\n",
296	                     count, (unsigned)MYVENDOR_FW_SLOT_KEEP);
297	            }
298	        }
299	
300	      if (count <= MYVENDOR_FW_SLOT_KEEP || !have)
301	        {
302	          return removed;
303	        }
304	
305	      if (unlink_bin(oldest.name) == 0)
306	        {
307	          removed++;
308	        }
309	      else
310	        {
311	          return removed;
312	        }
313	    }
314	}
