316	int myvendor_fw_slot_on_commit(const char *path)
317	{
318	  const char *base;
319	  size_t prefix = sizeof(MYVENDOR_FW_SLOT_DIR) - 1u;
320	
321	  if (path == NULL)
322	    {
323	      return 0;
324	    }
325	
326	  if (strncmp(path, MYVENDOR_FW_SLOT_DIR, prefix) != 0)
327	    {
328	      return 0;
329	    }
330	
331	  if (path[prefix] != '/')
332	    {
333	      return 0;
334	    }
335	
336	  base = path + prefix + 1u;
337	  if (strchr(base, '/') != NULL || !name_is_bin(base))
338	    {
339	      return 0;
340	    }
341	
342	  return myvendor_fw_slot_prune();
343	}
