345	int myvendor_fw_slot_delete_oldest(char *deleted_name, size_t n)
346	{
347	  struct fw_cand cands[MYVENDOR_FW_SLOT_SCAN_MAX];
348	  unsigned count;
349	  unsigned last;
350	
351	  count = scan_bins(cands, MYVENDOR_FW_SLOT_SCAN_MAX);
352	  if (count == 0)
353	    {
354	      return -ENOENT;
355	    }
356	
357	  if (count < 2)
358	    {
359	      return -EBUSY;
360	    }
361	
362	  last = count - 1u;
363	  if (unlink_bin(cands[last].name) != 0)
364	    {
365	      return errno != 0 ? -errno : -EIO;
366	    }
367	
368	  if (deleted_name != NULL && n > 0)
369	    {
370	      strncpy(deleted_name, cands[last].name, n - 1u);
371	      deleted_name[n - 1u] = '\0';
372	    }
373	
374	  return 0;
375	}
