124	/** @brief 去掉 KV 行尾空白与换行。 */
125	static void trim_line(char *buf)
126	{
127	  char *p;
128	  size_t n;
129	
130	  n = strlen(buf);
131	  while (n > 0)
132	    {
133	      char c = buf[n - 1];
134	
135	      if (c != '\0' && c != '\n' && c != '\r' && c != ' ' && c != '\t')
136	        {
137	          break;
138	        }
139	
140	      buf[--n] = '\0';
141	    }
142	
143	  p = buf;
144	  while (*p == ' ' || *p == '\t')
145	    {
146	      p++;
147	    }
148	
149	  if (p != buf)
150	    {
151	      memmove(buf, p, strlen(p) + 1);
152	    }
153	}
