155	#define KV_READ_OK      0
156	#define KV_READ_IO     -1
157	#define KV_READ_ABSENT -2
158	
159	/**
160	 * @brief 读 KV 文件一行。
161	 * @return KV_READ_OK / KV_READ_IO / KV_READ_ABSENT。
162	 */
163	static int read_kv_line(const char *path, char *buf, size_t buflen)
164	{
165	  int fd;
166	  ssize_t n;
167	
168	  if (path == NULL || buf == NULL || buflen < 2)
169	    {
170	      return KV_READ_IO;
171	    }
172	
173	  fd = open(path, O_RDONLY);
174	  if (fd < 0)
175	    {
176	      return errno == ENOENT ? KV_READ_ABSENT : KV_READ_IO;
177	    }
178	
179	  n = read(fd, buf, buflen - 1);
180	  close(fd);
181	  if (n <= 0)
182	    {
183	      return n == 0 ? KV_READ_ABSENT : KV_READ_IO;
184	    }
185	
186	  buf[n] = '\0';
187	  trim_line(buf);
188	  return buf[0] != '\0' ? KV_READ_OK : KV_READ_ABSENT;
189	}
