194	static int read_boot_kv_line(const char *key, char *buf, size_t buflen)
195	{
196	  char path[80];
197	
198	  snprintf(path, sizeof(path), BOOT_KV_DB_DIR "%s", key);
199	  return read_kv_line(path, buf, buflen);
