202	/**
203	 * @brief 解析 persist.boot.* 槽位字符串。
204	 * @param[out] fw_name 可选输出 fw 名。
205	 * @return #COMPANION_SLOT_*。
206	 */
207	static uint8_t parse_boot_slot(const char *buf, char *fw_name, size_t fw_name_len)
208	{
209	  if (buf == NULL || buf[0] == '\0')
210	    {
211	      return COMPANION_SLOT_UNKNOWN;
212	    }
213	
214	  if (fw_name != NULL && fw_name_len > 0)
215	    {
216	      fw_name[0] = '\0';
217	    }
218	
219	  if (strncmp(buf, "fw", 2) == 0 &&
220	      (buf[2] == '\0' || buf[2] == ' ' || buf[2] == '\t'))
221	    {
222	      const char *name = buf + 2;
223	
224	      while (*name == ' ' || *name == '\t')
225	        {
226	          name++;
227	        }
228	
229	      if (fw_name != NULL && fw_name_len > 0 && name[0] != '\0')
230	        {
231	          strncpy(fw_name, name, fw_name_len - 1);
232	          fw_name[fw_name_len - 1] = '\0';
233	        }
234	
235	      return COMPANION_SLOT_FW;
236	    }
237	
238	  if (strcmp(buf, "main") == 0)
239	    {
240	      return COMPANION_SLOT_MAIN;
241	    }
242	
243	  if (strcmp(buf, "factory") == 0)
244	    {
245	      return COMPANION_SLOT_FACTORY;
246	    }
247	
248	  return COMPANION_SLOT_UNKNOWN;
249	}
