251	static void bootinfo_load(void)
252	{
253	  char buf[96];
254	  const char *src = "running";
255	  int r;
256	
257	  if (g_bootinfo_ready)
258	    {
259	      return;
260	    }
261	
262	  g_boot_slot = COMPANION_SLOT_UNKNOWN;
263	  g_boot_fw_name[0] = '\0';
264	  g_boot_version[0] = '\0';
265	
266	  r = read_boot_kv_line(BOOT_RUNNING_KEY, buf, sizeof(buf));
267	  if (r == KV_READ_OK)
268	    {
269	      g_boot_slot = parse_boot_slot(buf, g_boot_fw_name,
270	                                   sizeof(g_boot_fw_name));
271	      g_bootinfo_ready = true;
272	    }
273	  else if (r == KV_READ_ABSENT)
274	    {
275	      /* 旧 2SFBL 不写 persist.boot.running。sticky target 在 fw/main/factory
276	       * 时就是这次实际加载的槽（F 热键进工厂除外）。
277	       */
278	
279	      r = read_boot_kv_line(BOOT_TARGET_KEY, buf, sizeof(buf));
280	      if (r == KV_READ_OK)
281	        {
282	          src = "target";
283	          g_boot_slot = parse_boot_slot(buf, g_boot_fw_name,
284	                                       sizeof(g_boot_fw_name));
285	          g_bootinfo_ready = true;
286	        }
287	      else if (r == KV_READ_ABSENT)
288	        {
289	          src = "none";
290	          g_bootinfo_ready = true;
291	        }
292	      else
293	        {
294	          src = "none";
295	        }
296	    }
297	  else
298	    {
299	      src = "none";
300	    }
301	
302	  if (g_bootinfo_ready)
303	    {
304	      if (read_boot_kv_line(BOOT_VERSION_KEY, buf, sizeof(buf)) == KV_READ_OK)
305	        {
306	          strncpy(g_boot_version, buf, sizeof(g_boot_version) - 1);
307	          g_boot_version[sizeof(g_boot_version) - 1] = '\0';
308	        }
309	    }
310	
311	  syslog(LOG_INFO, "bootinfo: via=%s slot=%u fw=%s sw=%s hw=%s boot=%s\n",
312	         src,
313	         (unsigned)g_boot_slot,
314	         g_boot_fw_name[0] != '\0' ? g_boot_fw_name : "-",
315	         CONFIG_MYVENDOR_PRODUCT_VERSION,
316	         CONFIG_MYVENDOR_HARDWARE_VERSION,
317	         g_boot_version[0] != '\0' ? g_boot_version : "-");
318	}
