347	/**
348	 * @brief 写 `persist.boot.target` 为 fw 或 main（带结尾 NUL，对齐 2SFBL）。
349	 */
350	int myvendor_boot_target_set(uint8_t slot)
351	{
352	  const char *name;
353	  char path[80];
354	  char buf[8];
355	  size_t n;
356	  int fd;
357	  int ret;
358	
359	  if (slot == COMPANION_SLOT_FW)
360	    {
361	      name = "fw";
362	    }
363	  else if (slot == COMPANION_SLOT_MAIN)
364	    {
365	      name = "main";
366	    }
367	  else
368	    {
369	      return -EINVAL;
370	    }
371	
372	  ret = mkdir(BOOT_KV_DB_PATH, 0755);
373	  if (ret < 0 && errno != EEXIST)
374	    {
375	      syslog(LOG_WARNING, "bootinfo: mkdir %s errno=%d\n",
376	             BOOT_KV_DB_PATH, errno);
377	      return -errno;
378	    }
379	
380	  snprintf(path, sizeof(path), BOOT_KV_DB_DIR "%s", BOOT_TARGET_KEY);
381	  n = strlen(name);
382	  memcpy(buf, name, n);
383	  buf[n] = '\0';
384	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
385	  if (fd < 0)
386	    {
387	      syslog(LOG_WARNING, "bootinfo: target %s open errno=%d\n",
388	             name, errno);
389	      return -errno;
390	    }
391	
392	  if (write(fd, buf, n + 1u) != (ssize_t)(n + 1u))
393	    {
394	      int err = errno;
395	
396	      close(fd);
397	      syslog(LOG_WARNING, "bootinfo: target %s write errno=%d\n", name, err);
398	      return err != 0 ? -err : -EIO;
399	    }
400	
401	  close(fd);
402	  syslog(LOG_INFO, "bootinfo: target=%s\n", name);
403	  return 0;
404	}
