128	/**
129	 * @brief route_worker_thread 接口。
130	 */
131	static void * route_worker_thread(void * arg)
132	{
133	    (void)arg;
134	
135	    for (;;) {
136	        route_plan_job_t job;
137	        route_plan_result_t * local = NULL;
138	        vmap_route_pt_t * pts_tmp = NULL;
139	        vmap_route_maneuver_t mans[VMAP_ROUTE_MAX_MANEUVERS];
140	        uint32_t pt_count = 0;
141	        uint32_t man_count = 0;
142	        double total_m = 0.0;
143	        uint32_t regions_planned = 0;
144	        bool ok = false;
145	        bool cancel;
146	
147	        while (atomic_load_explicit(&g_worker.thread_run, memory_order_acquire)
148	            && !atomic_load_explicit(&g_worker.has_job, memory_order_acquire)) {
149	            (void)sem_wait(&g_worker.wake);
150	        }
151	
152	        if (!atomic_load_explicit(&g_worker.thread_run, memory_order_acquire)) {
153	            break;
154	        }
155	
156	        pthread_mutex_lock(&g_worker.job_lock);
157	        job = g_worker.job;
158	        atomic_store_explicit(&g_worker.has_job, false, memory_order_release);
159	        pthread_mutex_unlock(&g_worker.job_lock);
160	
161	        atomic_store_explicit(&g_worker.running, true, memory_order_release);
162	        cancel = atomic_exchange_explicit(&g_worker.cancel, false, memory_order_acq_rel);
163	        vmap_route_plan_yield();
164	
165	        if (!cancel && job.cb != NULL) {
166	            pts_tmp = (vmap_route_pt_t *)board_malloc_psram(
167	                (size_t)VMAP_ROUTE_MAX_PTS * sizeof(vmap_route_pt_t));
168	            if (pts_tmp == NULL || !board_ptr_in_psram_pool(pts_tmp)) {
169	                board_mem_free(pts_tmp);
170	                VMAP_NAV_ERR("worker: pts scratch alloc failed");
171	            } else if (job.map_dir[0] == '\0') {
172	                VMAP_NAV_ERR("worker: missing map_dir");
173	                board_mem_free(pts_tmp);
174	            } else if (job.kind == VMAP_ROUTE_JOB_ROLLING) {
175	                VMAP_NAV_OUT("worker: rolling compute begin");
176	                ok = vmap_route_compute_rolling(&job.rolling, pts_tmp, &pt_count,
177	                    &total_m, mans, VMAP_ROUTE_MAX_MANEUVERS, &man_count,
178	                    &regions_planned);
179	                VMAP_NAV_OUT("worker: rolling compute %s pts=%u regions=%u",
180	                    ok ? "ok" : "fail", pt_count, regions_planned);
181	            } else if (vmap_route_corridor_needed(job.map_dir, job.from_lon,
182	                    job.from_lat, job.to_lon, job.to_lat)) {
183	                VMAP_NAV_OUT("worker: corridor compute begin");
184	                ok = vmap_route_compute_corridor(job.map_dir, job.from_lon,
185	                    job.from_lat, job.to_lon, job.to_lat, pts_tmp, &pt_count,
186	                    &total_m, mans, VMAP_ROUTE_MAX_MANEUVERS, &man_count);
187	                VMAP_NAV_OUT("worker: corridor compute %s pts=%u man=%u",
188	                    ok ? "ok" : "fail", pt_count, man_count);
189	            } else if (job.graph != NULL) {
190	                VMAP_NAV_OUT("worker: compute begin");
191	                ok = vmap_route_compute(job.graph, job.from_lon, job.from_lat,
192	                    job.to_lon, job.to_lat, pts_tmp, &pt_count, &total_m,
193	                    mans, VMAP_ROUTE_MAX_MANEUVERS, &man_count);
194	                VMAP_NAV_OUT("worker: compute %s pts=%u man=%u",
195	                    ok ? "ok" : "fail", pt_count, man_count);
196	            } else {
197	                VMAP_NAV_ERR("worker: no graph and not corridor");
198	                board_mem_free(pts_tmp);
199	                pts_tmp = NULL;
200	            }
201	
202	            if (pts_tmp != NULL) {
203	                if (ok) {
204	                    local = route_worker_result_alloc(&job, true, regions_planned,
205	                        pts_tmp, pt_count, total_m, mans, man_count);
206	                } else {
207	                    local = route_worker_result_alloc(&job, false, 0, NULL, 0,
208	                        0.0, NULL, 0);
209	                }
210	                board_mem_free(pts_tmp);
211	            } else {
212	                local = route_worker_result_alloc(&job, false, 0, NULL, 0,
213	                    0.0, NULL, 0);
214	            }
215	        } else {
216	            VMAP_NAV_WARN("worker: skipped cancel=%d graph=%p cb=%p",
217	                cancel ? 1 : 0, (void *)job.graph, (void *)job.cb);
218	        }
219	
220	        if (local != NULL) {
221	            bool skip_done = vmap_route_plan_aborted()
222	                || atomic_load_explicit(&g_worker.cancel, memory_order_acquire);
223	
224	            pthread_mutex_lock(&g_worker.job_lock);
225	            if (g_worker.job.cb == NULL) {
226	                skip_done = true;
227	            }
228	            pthread_mutex_unlock(&g_worker.job_lock);
229	            if (skip_done) {
230	                board_mem_free(local);
231	                local = NULL;
232	            }
233	        }
234	
235	        atomic_store_explicit(&g_worker.running, false, memory_order_release);
236	
237	        if (local == NULL) {
238	            continue;
239	        }
240	
241	        (void)lv_async_call(route_worker_async_done, local);
242	    }
243	
244	    return NULL;
245	}
