247	/**
248	 * @brief vmap route worker init。
249	 * @return 0 成功，负 errno 失败。
250	 */
251	void vmap_route_worker_init(void)
252	{
253	    bool expected = false;
254	    pthread_attr_t attr;
255	    int ret;
256	
257	    if (!atomic_compare_exchange_strong(&g_worker_inited, &expected, true)) {
258	        return;
259	    }
260	
261	    memset(&g_worker, 0, sizeof(g_worker));
262	    g_worker_stack = (uint8_t *)board_malloc_psram(CONFIG_VMAP_ROUTE_WORKER_STACK);
263	    if (g_worker_stack == NULL || !board_ptr_in_psram_pool(g_worker_stack)) {
264	        board_mem_free(g_worker_stack);
265	        g_worker_stack = NULL;
266	        atomic_store_explicit(&g_worker_inited, false, memory_order_release);
267	        VMAP_NAV_ERR("worker: PSRAM stack alloc failed");
268	        return;
269	    }
270	
271	    sem_init(&g_worker.wake, 0, 0);
272	    pthread_mutex_init(&g_worker.job_lock, NULL);
273	    atomic_store_explicit(&g_worker.thread_run, true, memory_order_release);
274	
275	    pthread_attr_init(&attr);
276	    ret = pthread_attr_setstack(&attr, g_worker_stack,
277	        CONFIG_VMAP_ROUTE_WORKER_STACK);
278	    if (ret == 0) {
279	        ret = pthread_create(&g_worker.thread, &attr, route_worker_thread, NULL);
280	    }
281	
282	    pthread_attr_destroy(&attr);
283	    if (ret != 0) {
284	        sem_destroy(&g_worker.wake);
285	        pthread_mutex_destroy(&g_worker.job_lock);
286	        board_mem_free(g_worker_stack);
287	        g_worker_stack = NULL;
288	        atomic_store_explicit(&g_worker_inited, false, memory_order_release);
289	        VMAP_NAV_ERR("worker: thread create failed %d", ret);
290	        return;
291	    }
292	
293	#ifndef CONFIG_DISABLE_PTHREAD
294	    pthread_setname_np(g_worker.thread, "route_worker");
295	#endif
296	    {
297	        struct sched_param sp;
298	
299	        /* 低于 bicycle_ui（通常 100），规划时 UI 能抢占；idle 仍靠 usleep。 */
300	        memset(&sp, 0, sizeof(sp));
301	        sp.sched_priority = 80;
302	        (void)pthread_setschedparam(g_worker.thread, SCHED_FIFO, &sp);
303	    }
304	}
