306	/**
307	 * @brief vmap route worker shutdown。
308	 */
309	void vmap_route_worker_shutdown(void)
310	{
311	    if (!atomic_load_explicit(&g_worker_inited, memory_order_acquire)) {
312	        return;
313	    }
314	
315	    atomic_store_explicit(&g_worker.thread_run, false, memory_order_release);
316	    atomic_store_explicit(&g_worker.has_job, true, memory_order_release);
317	    sem_post(&g_worker.wake);
318	    pthread_join(g_worker.thread, NULL);
319	    sem_destroy(&g_worker.wake);
320	    pthread_mutex_destroy(&g_worker.job_lock);
321	    board_mem_free(g_worker_stack);
322	    g_worker_stack = NULL;
323	    atomic_store_explicit(&g_worker_inited, false, memory_order_release);
324	}
