356	/**
357	 * @brief vmap route worker submit。
358	 */
359	bool vmap_route_worker_submit(const char * map_dir, vmap_route_graph_t * graph,
360	    double from_lon, double from_lat, double to_lon, double to_lat,
361	    vmap_route_worker_done_cb cb, void * user)
362	{
363	    if (!map_dir || map_dir[0] == '\0' || !cb) {
364	        VMAP_NAV_ERR("submit: bad args map_dir=%p cb=%p", (void *)map_dir, (void *)cb);
365	        return false;
366	    }
367	
368	    if (!vmap_route_corridor_needed(map_dir, from_lon, from_lat, to_lon, to_lat)
369	        && graph == NULL) {
370	        VMAP_NAV_ERR("submit: graph required for same-region plan");
371	        return false;
372	    }
373	
374	    vmap_route_worker_init();
375	    if (!atomic_load_explicit(&g_worker_inited, memory_order_acquire)) {
376	        VMAP_NAV_ERR("submit: worker not started");
377	        return false;
378	    }
379	
380	    pthread_mutex_lock(&g_worker.job_lock);
381	    if (atomic_load_explicit(&g_worker.has_job, memory_order_acquire)
382	        || atomic_load_explicit(&g_worker.running, memory_order_acquire)) {
383	        pthread_mutex_unlock(&g_worker.job_lock);
384	        VMAP_NAV_WARN("submit: worker busy");
385	        return false;
386	    }
387	
388	    g_worker.job.kind = VMAP_ROUTE_JOB_STANDARD;
389	    memset(&g_worker.job.rolling, 0, sizeof(g_worker.job.rolling));
390	    strncpy(g_worker.job.map_dir, map_dir, sizeof(g_worker.job.map_dir) - 1);
391	    g_worker.job.map_dir[sizeof(g_worker.job.map_dir) - 1] = '\0';
392	    g_worker.job.graph = graph;
393	    g_worker.job.from_lon = from_lon;
394	    g_worker.job.from_lat = from_lat;
395	    g_worker.job.to_lon = to_lon;
396	    g_worker.job.to_lat = to_lat;
397	    g_worker.job.cb = cb;
398	    g_worker.job.user = user;
399	    vmap_route_plan_abort_clear();
400	    atomic_store_explicit(&g_worker.cancel, false, memory_order_release);
401	    atomic_store_explicit(&g_worker.has_job, true, memory_order_release);
402	    pthread_mutex_unlock(&g_worker.job_lock);
403	
404	    sem_post(&g_worker.wake);
405	    return true;
406	}
